instrument TAS_instrument {
    // Instrument parameters
    double KF = 5;
    double KI = 0;
    double QM = 0.5;
    double EN = 0;
    int verbose = 1;
    double WM = 0.233;
    double HM = 0.197;
    double RMH = -1;
    double RMV = -1;
    double DM = 1.807;
    int NHM = 15;
    int NVM = 15;
    double WA = 0.16;
    double HA = 0.08;
    double RAH = -1;
    double RAV = -1;
    double DA = 2.087;
    int NHA = 15;
    int NVA = 15;
    double L1 = 2.3;
    double ALF1 = 60;
    double ALF2 = 60;
    double ALF3 = 60;
    double ALF4 = 60;
    double BET1 = 120;
    double BET2 = 120;
    double BET3 = 120;
    double BET4 = 120;
    double Sqw_coh = 1.0; // Assuming V.lau is a placeholder for 1.0

    // Define source
    Source_gen source (
        radius = 0.10,
        dist = L1,
        focus_xw = fabs(WM*sin(ALF1*DEG2RAD)),
        focus_yh = HM,
        E0 = EN,
        dE = EN*0.03,
        I1 = 0.5874e+13,
        T1 = 683.7,
        T2 = 257.7,
        I2 = 2.5099e+13,
        T3 = 16.7,
        I3 = 1.0343e+12
    ) AT (0, 0, 0) RELATIVE ABSOLUTE;

    // Define collimator
    Collimator_linear collimator (
        xmin = -WM/2,
        xmax = WM/2,
        ymin = -HM/2,
        ymax = HM/2,
        length = L1/2,
        divergence = ALF1,
        divergenceV = BET1
    ) AT (0, 0, L1/4) RELATIVE ABSOLUTE;

    // Define sample
    Sample sample (
        material = "Si",
        hkl = 1 1 1,
        T = 300,
        I = 1.0,
        coh = 1.0,
        incoh = 0.0
    ) AT (0, 0, L1) RELATIVE ABSOLUTE;

    // Define analyzer
    Collimator_linear analyzer (
        xmin = -WA/2,
        xmax = WA/2,
        ymin = -HA/2,
        ymax = HA/2,
        length = DA/2,
        divergence = ALF4,
        divergenceV = BET4
    ) AT (0, 0, L1 + DM + DA/2) RELATIVE ABSOLUTE;

    // Define detectors
    Monitor_nexus monitor1 AT (0, 0, L1/2) RELATIVE ABSOLUTE;
    Monitor_nexus monitor2 AT (0, 0, L1 + DM/2) RELATIVE ABSOLUTE;
    Monitor_nexus monitor3 AT (0, 0, L1 + DM + DA/2) RELATIVE ABSOLUTE;

    // Define progress bar
    Progress_bar progress AT (0, 0, 0) RELATIVE ABSOLUTE;

    // Define beam path
    source -> collimator -> sample -> analyzer -> monitor3;
    source -> collimator -> monitor1;
    source -> monitor2;

    // Define output
    output {
        print("Integrated intensity on monitor1: %f ± %f (events: %d, ncount: %d, seed: %d)", 
              monitor1.intensity, monitor1.error, monitor1.count, ncount, seed);
        print("Integrated intensity on monitor2: %f ± %f (events: %d, ncount: %d, seed: %d)", 
              monitor2.intensity, monitor2.error, monitor2.count, ncount, seed);
        print("Integrated intensity on monitor3: %f ± %f (events: %d, ncount: %d, seed: %d)", 
              monitor3.intensity, monitor3.error, monitor3.count, ncount, seed);
    }
}
```

